import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Book {
    private String isbn;
    private String title;
    private String author;
    private boolean isAvailable;

    public Book(String isbn, String title, String author) {
        if (isbn == null || isbn.trim().isEmpty()) throw new IllegalArgumentException("ISBN required.");
        if (title == null || title.trim().isEmpty()) throw new IllegalArgumentException("Title required.");
        this.isbn = isbn.trim();
        this.title = title.trim();
        this.author = (author != null) ? author.trim() : "Unknown Author";
        this.isAvailable = true;
    }

    public boolean borrowBook() {
        if (!isAvailable) return false;
        this.isAvailable = false;
        return true;
    }

    public void returnBook() {
        this.isAvailable = true;
    }

    public String getIsbn() { return isbn; }
    public String getTitle() { return title; }
    public String getAuthor() { return author; }
    public boolean isAvailable() { return isAvailable; }
}

class Member {
    public static final int MAX_LOANS = 3;
    private String memberId;
    private String name;
    private List<Book> borrowedBooks;

    public Member(String memberId, String name) {
        this.memberId = memberId;
        this.name = name;
        this.borrowedBooks = new ArrayList<>();
    }

    public boolean canBorrow() {
        return borrowedBooks.size() < MAX_LOANS;
    }

    public boolean addBorrowedBook(Book book) {
        if (!canBorrow() || borrowedBooks.contains(book)) return false;
        borrowedBooks.add(book);
        return true;
    }

    public boolean removeBorrowedBook(Book book) {
        return borrowedBooks.remove(book);
    }

    // Defensive copy: return unmodifiable list
    public List<Book> getBorrowedBooks() {
        return Collections.unmodifiableList(borrowedBooks);
    }

    public String getMemberId() { return memberId; }
    public String getName() { return name; }
}

class Library {
    private List<Book> catalog = new ArrayList<>();
    private List<Member> members = new ArrayList<>();

    public void addBook(Book book) {
        if (book != null) catalog.add(book);
    }

    public void registerMember(Member member) {
        if (member != null) members.add(member);
    }

    public Book findBook(String isbn) {
        for (Book b : catalog) {
            if (b.getIsbn().equalsIgnoreCase(isbn)) return b;
        }
        return null;
    }

    public Member findMember(String memberId) {
        for (Member m : members) {
            if (m.getMemberId().equalsIgnoreCase(memberId)) return m;
        }
        return null;
    }

    public boolean issueBook(String isbn, String memberId) {
        Book book = findBook(isbn);
        Member member = findMember(memberId);

        if (book == null) {
            System.err.printf("Error: Book with ISBN %s not found.%n", isbn);
            return false;
        }
        if (member == null) {
            System.err.printf("Error: Member with ID %s not found.%n", memberId);
            return false;
        }
        if (!book.isAvailable()) {
            System.err.printf("Error: '%s' is already checked out.%n", book.getTitle());
            return false;
        }
        if (!member.canBorrow()) {
            System.err.printf("Error: %s has reached the maximum borrowing quota (%d books).%n", 
                member.getName(), Member.MAX_LOANS);
            return false;
        }

        book.borrowBook();
        member.addBorrowedBook(book);
        System.out.printf("Success: '%s' issued to %s.%n", book.getTitle(), member.getName());
        return true;
    }

    public boolean returnBook(String isbn, String memberId) {
        Book book = findBook(isbn);
        Member member = findMember(memberId);

        if (book == null || member == null) return false;
        if (!member.getBorrowedBooks().contains(book)) {
            System.err.printf("Error: %s did not borrow '%s'.%n", member.getName(), book.getTitle());
            return false;
        }

        book.returnBook();
        member.removeBorrowedBook(book);
        System.out.printf("Success: '%s' returned by %s.%n", book.getTitle(), member.getName());
        return true;
    }

    public void printCatalogStatus() {
        System.out.println("=========================================================================================");
        System.out.println("                                CITY LIBRARY CATALOG                                     ");
        System.out.println("=========================================================================================");
        System.out.printf("%-16s %-32s %-24s %s%n", "ISBN", "Title", "Author", "Status");
        System.out.println("-----------------------------------------------------------------------------------------");
        for (Book b : catalog) {
            System.out.printf("%-16s %-32s %-24s %s%n", 
                b.getIsbn(), 
                (b.getTitle().length() > 30 ? b.getTitle().substring(0, 27) + "..." : b.getTitle()), 
                b.getAuthor(), 
                b.isAvailable() ? "[AVAILABLE]" : "[BORROWED]");
        }
        System.out.println("=========================================================================================\n");
    }
}

